import { Component, OnInit } from '@angular/core';
import { DestinationService } from '../../../services/destination.service';
import { CountryDto } from '../../../models/destination.model';

@Component({
    selector: 'app-suggestions',
    templateUrl: './suggestions.component.html'
})
export class SuggestionsComponent implements OnInit {
    suggestions: CountryDto[] = [];
    loading = false;
    error = '';
    selectedSuggestions: CountryDto[] = [];

    constructor(private destinationService: DestinationService) { }

    ngOnInit(): void {
        this.getSuggestions();
    }

    getSuggestions(): void {
        this.loading = true;
        this.destinationService.getSuggestions()
            .subscribe({
                next: (response) => {
                    this.suggestions = response.data;
                    this.loading = false;
                },
                error: (e) => {
                    this.error = 'Failed to load suggestions';
                    this.loading = false;
                }
            });
    }

    addSelected() {
        // Implement logic to add selected suggestions to our DB
        alert('Implement bulk add logic here based on your backend needs');
    }
}
